package com.sih.support.repository; import com.sih.support.entity.*; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; public final class Repositories { private Repositories(){} public interface Meals extends JpaRepository<MealOrder,Long>{List<MealOrder>findByTenantIdOrderByScheduledOnDesc(String t);Optional<MealOrder>findByIdAndTenantId(Long i,String t);} public interface EquipmentRepo extends JpaRepository<Equipment,Long>{List<Equipment>findByTenantIdOrderByNameAsc(String t);Optional<Equipment>findByIdAndTenantId(Long i,String t);} public interface WorkOrders extends JpaRepository<MaintenanceWorkOrder,Long>{List<MaintenanceWorkOrder>findByTenantIdOrderByDueOnAsc(String t);Optional<MaintenanceWorkOrder>findByIdAndTenantId(Long i,String t);} public interface CleaningRepo extends JpaRepository<CleaningTask,Long>{List<CleaningTask>findByTenantIdOrderByRequestedAtDesc(String t);Optional<CleaningTask>findByIdAndTenantId(Long i,String t);} }